 "content": "from functools import lru_cache


def transform(grid):
    h, w = len(grid), len(grid[0])
    occupied = frozenset((r, c) for r in range(h) for c in range(w) if grid[r][c] != 0)
    if not occupied:
        return [row[:] for row in grid]

    # The figure is tiled by 2x2 squares and 3-cell L pieces. Each L is
    # identified by the missing corner of its 2x2 bounding box.
    placements = []
    for r in range(h - 1):
        for c in range(w - 1):
            box = frozenset(((r, c), (r + 1, c), (r, c + 1), (r + 1, c + 1)))
            if box <= occupied:
                placements.append((1, box))
            for dr in range(2):
                for dc in range(2):
                    cells = box - {(r + dr, c + dc)}
                    if cells <= occupied:
                        # Missing top-left -> 2, bottom-left -> 3,
                        # top-right -> 4, bottom-right -> 5.
                        color = {(0, 0): 2, (1, 0): 3, (0, 1): 4, (1, 1): 5}[(dr, dc)]
                        placements.append((color, cells))

    by_cell = {cell: [] for cell in occupied}
    for color, cells in placements:
        for cell in cells:
            by_cell[cell].append((color, cells))

    @lru_cache(None)
    def tile(remaining):
        if not remaining:
            return ()
        rem = set(remaining)
        cell = min(rem, key=lambda p: sum(cells <= rem for _, cells in by_cell[p]))
        for color, cells in by_cell[cell]:
            if cells <= rem:
                rest = tile(tuple(sorted(rem - cells)))
                if rest is not None:
                    return ((color, tuple(cells)),) + rest
        return None

    solution = tile(tuple(sorted(occupied)))
    if solution is None:
        return [row[:] for row in grid]
    output = [[0 for _ in range(w)] for _ in range(h)]
    for color, cells in solution:
        for r, c in cells:
            output[r][c] = color
    return output


